`timescale 1 ps / 1 ps
module  arriaii_pciehip_dprio_addr
	( 
	incr_addr,
	mdc,
	mdio_in,
	reg_addr,
	reset,
	shift_addr) /* synthesis synthesis_clearbox=1 */;
	input   incr_addr;
	input   mdc;
	input   mdio_in;
	output   [15:0]  reg_addr;
	input   reset;
	input   shift_addr;

	reg	nlO0i13;
	reg	nlO0i14;
	reg	nlO0l11;
	reg	nlO0l12;
	reg	nlO0O10;
	reg	nlO0O9;
	reg	nlOii7;
	reg	nlOii8;
	reg	nlOil5;
	reg	nlOil6;
	reg	nlOli3;
	reg	nlOli4;
	reg	nlOOi1;
	reg	nlOOi2;
	reg	n0il;
	reg	n0iO;
	reg	n0li;
	reg	n0ll;
	reg	n0lO;
	reg	n0Oi;
	reg	n0Ol;
	reg	n0OO;
	reg	ni0i;
	reg	ni0l;
	reg	ni0O;
	reg	ni1i;
	reg	ni1l;
	reg	ni1O;
	reg	niii;
	reg	niil;
	reg	nili;
	reg	niiO_clk_prev;
	wire	wire_niiO_CLRN;
	wire	wire_niiO_PRN;
	wire	wire_n0i_dataout;
	wire	wire_n0l_dataout;
	wire	wire_n0O_dataout;
	wire	wire_n1i_dataout;
	wire	wire_n1l_dataout;
	wire	wire_n1O_dataout;
	wire	wire_nii_dataout;
	wire	wire_nil_dataout;
	wire	wire_nill_dataout;
	wire	wire_nilO_dataout;
	wire	wire_niO_dataout;
	wire	wire_niOi_dataout;
	wire	wire_niOl_dataout;
	wire	wire_niOO_dataout;
	wire	wire_nl0i_dataout;
	wire	wire_nl0l_dataout;
	wire	wire_nl0O_dataout;
	wire	wire_nl1i_dataout;
	wire	wire_nl1l_dataout;
	wire	wire_nl1O_dataout;
	wire	wire_nli_dataout;
	wire	wire_nlii_dataout;
	wire	wire_nlil_dataout;
	wire	wire_nliO_dataout;
	wire	wire_nll_dataout;
	wire	wire_nlli_dataout;
	wire	wire_nlll_dataout;
	wire	wire_nllO_dataout;
	wire	wire_nlO_dataout;
	wire	wire_nlOi_dataout;
	wire	wire_nlOl_dataout;
	wire	wire_nlOO_dataout;
	wire  [15:0]   wire_ni_o;
	wire  nlO1O;
	wire  nlOiO;
	wire  nlOlO;

	initial
		nlO0i13 = 0;
	always @ ( posedge mdc)
		  nlO0i13 <= nlO0i14;
	event nlO0i13_event;
	initial
		#1 ->nlO0i13_event;
	always @(nlO0i13_event)
		nlO0i13 <= {1{1'b1}};
	initial
		nlO0i14 = 0;
	always @ ( posedge mdc)
		  nlO0i14 <= nlO0i13;
	initial
		nlO0l11 = 0;
	always @ ( posedge mdc)
		  nlO0l11 <= nlO0l12;
	event nlO0l11_event;
	initial
		#1 ->nlO0l11_event;
	always @(nlO0l11_event)
		nlO0l11 <= {1{1'b1}};
	initial
		nlO0l12 = 0;
	always @ ( posedge mdc)
		  nlO0l12 <= nlO0l11;
	initial
		nlO0O10 = 0;
	always @ ( posedge mdc)
		  nlO0O10 <= nlO0O9;
	initial
		nlO0O9 = 0;
	always @ ( posedge mdc)
		  nlO0O9 <= nlO0O10;
	event nlO0O9_event;
	initial
		#1 ->nlO0O9_event;
	always @(nlO0O9_event)
		nlO0O9 <= {1{1'b1}};
	initial
		nlOii7 = 0;
	always @ ( posedge mdc)
		  nlOii7 <= nlOii8;
	event nlOii7_event;
	initial
		#1 ->nlOii7_event;
	always @(nlOii7_event)
		nlOii7 <= {1{1'b1}};
	initial
